
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_ccalda_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_ccalda", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.180998796936805e-01, -1.175098655931054e-01, -1.166632982154134e-01, -1.154500632678784e-01, -1.137144190663829e-01, -1.112379431319849e-01, -1.077182272443744e-01, -1.027451389117132e-01, -9.578097386102929e-02, -8.609788742427342e-02, -7.180800669045616e-02, -5.832518332402500e-02, -5.312521365517298e-02, -4.356490951052762e-02, -3.281123664641244e-02, -2.046972905770784e-02, -9.021359516843025e-03, -2.245537380012278e-03, -2.518209275716026e-04, -1.111961672320747e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


